	int32_t repeatCooldown;  // +0x0C T: frames before the next script selection (CPU_RepeatCooldownFramesForDifficulty); counted down
	int32_t targetDx;  // +0x10 T: dx to the nearest opponent (Actor_FindNearestEnemyByXY)
	int32_t targetDy;  // +0x14 T
