struct MbrCharEntry {
	uint32_t valid;  // +0x00 T: set to 1 by CharaSelect_BuildCharTableWithUnlocks for available entries (0 in the file)
	char shortName[48];  // +0x04 T D: names the .wmt, win/face/ED bitmaps, story files ('AKIHA', 'HISUI&KOHAKU', 'M_HISUI', ...)
	char memberName0[32];  // +0x34 T D: file stem of data\<stem>.dat / .cpf / _c.ct and cut-in / voice names (equals shortName except HISUI&KOHAKU -> HISUI)
	char memberName1[32];  // +0x54 T D: partner stem: first char '0' = no partner, '1' = flag only (team.scriptedCharacterFlag = 1, no partner loaded), anything else = partner character files (KOHAKU)
	int32_t compactIndex;  // +0x74 U: written by the build routine, no reader found
	int32_t charId;  // +0x78 T D: index into g_CharTable; copied to actor.characterId
	int32_t stageId;  // +0x7C T D: g_LastCharStage on pick
	uint32_t unlockMask;  // +0x80 T D: hidden unless (mask & g_UnlockMask) != 0 (0 = always available)
	uint32_t lockedFlag;  // +0x84 T D: non-zero = locked copy
	int32_t reserved_88;  // +0x88 U: zero in the file, no reader found
	int32_t reserved_8C;  // +0x8C U: no reader found (equals charId except SATSUKI 16 and ids >= 18)
	int32_t altCharId;  // +0x90 T D: -1 none; pressing pause on the CSS jumps the cursor to this character
	int32_t portraitAnchorX;  // +0x94 T D: CSS_DrawPanelPortraitAndInfo (halved)
	int32_t portraitAnchorY;  // +0x98 T D
	int32_t notSelectableTile;  // +0x9C T D: 1 = non-character tile (skipped by the random roulette)
	int32_t cursorX;  // +0xA0 T D: CSS cursor icon x = value + 4
	int32_t cursorY;  // +0xA4 T D: y = value - 4
	int32_t effectAnchorX;  // +0xA8 T: copied into effect 0x33; 0 in the file
	int32_t effectAnchorY;  // +0xAC T
	uint8_t selectable;  // +0xB0 T: set to 1 by the build routine, 0 for locked copies
	uint8_t neighbourUp;  // +0xB1 T D: CSS cursor neighbour by numpad direction 8 (char id)
	uint8_t neighbourDown;  // +0xB2 T D: direction 2
	uint8_t neighbourLeft;  // +0xB3 T D: direction 4
	uint8_t neighbourRight;  // +0xB4 T D: direction 6
	uint8_t reserved_B5[3];  // +0xB5 D: zero, no reader
	int32_t vsArtOffsetX;  // +0xB8 T D: x shift of the hero art on the VS screen / CSS
	int32_t winArtOffsetX;  // +0xBC T D: x shift on the win screen
	uint32_t hiddenFlag;  // +0xC0 T D: non-zero hides the entry (1 for GAKIHA, NECO, AOKO, WLEN, F_CIEL)
};
