	int32_t damageRankScore;  // +0x10 T: drawn as the score (HUD_DrawScoreAndCredits)
	int32_t maxComboHits;  // +0x14 T: HUD_UpdateComboCounters
	int32_t hitsLandedCount;  // +0x18 T
	int32_t maxComboDamage;  // +0x1C T: folded into g_CharStatMaxDamage at round end
	int32_t reserved_20[2];  // +0x20 U: no reader found
	int32_t sideIndexCopy;  // +0x28 T: reset to the side index by Battle_ResetTeamAndMatchState
	int32_t counterHitCount;  // +0x2C T
	int32_t elapsedFrames;  // +0x30 T: accumulates g_RoundElapsedFrames
	int32_t counterA;  // +0x34 U: with counterB drawn clamped to 99 after the score
	int32_t counterB;  // +0x38 U
	int32_t autoGuardOption;  // +0x3C T: Actor_ResolveIncomingHits guard decision
	int32_t handicapLevel;  // +0x40 T: index of g_HandicapDamageDealtScale / TakenScale
	int32_t infiniteHeatOption;  // +0x44 T: arcade: heat gauge never depletes and heat mode 2 starts immediately (Character_UpdateStunMashAndHeatActivation); also read by the HUD banner
